describe("complete authority bindings", () => {
  for (const fixture of issue433Cases) it(fixture.name, () => {
    const i = structuredClone(fixture.input), before = JSON.stringify(i), l = i.legacy
    // These checks precede the old core failure for legal null-anchor/multiple-cycle RED.
    expect(hash(JSON.stringify([{enterpriseId:l.enterpriseId,asOf:l.asOf,ruleVersion:l.ruleVersion,assessmentVersion:l.assessmentVersion},l.titles]))).toBe(l.snapshotId)
    expect(i.formal).toEqual(fixture.input.formal)
    freeze(i)
    if ('error' in fixture.expected) expect(() => comparePlatformComparison(i)).toThrow(new Error(fixture.expected.error))
    else expect(comparePlatformComparison(i)).toEqual(fixture.expected)
    expect(JSON.stringify(i)).toBe(before)
  })
  it("repeated authority reads do not leak state", () => {
    for (const name of ['issue433_failed_only_null_anchor','issue433_two_unknown_grants','issue433_failed_only_null_anchor','issue433_unknown_grants_reverse']) {
      const f=issue433Cases.find(c=>c.name===name)!, i=freeze(structuredClone(f.input)), before=JSON.stringify(i)
      expect(comparePlatformComparison(i)).toEqual(f.expected)
      expect(JSON.stringify(i)).toBe(before)
    }
  })
  it('issue433_set_order_and_multiplicity', () => {
    for (const names of [['issue433_two_unknown_grants','issue433_unknown_grants_reverse'],['issue433_tied_latest_awards','issue433_direct_award_order']]) {
      const fixtures=names.map(name=>issue433Cases.find(c=>c.name===name)!)
      expect(fixtures[0]!.expected).toEqual(fixtures[1]!.expected)
      for(const f of fixtures) expect(comparePlatformComparison(freeze(structuredClone(f.input)))).toEqual(f.expected)
    }
    const f=issue433Cases.find(c=>c.name==='issue433_duplicate_binding')!
    expect(()=>comparePlatformComparison(f.input)).toThrow(new Error('invalid_cycle_join'))
  })
  it('issue433_legal_40_and_rejected_41_cycles', () => {
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_two_known_batches')!.input)
    const a=i.formal.assessment, binding=i.formal.cycles[0]!, event=a.evidence[0]!, source=a.sourceVersions[0]!
    i.formal.cycles=[];a.cycles=[];a.evidence=[];a.sourceVersions=[]
    const expected=[]
    for(let id=1;id<=40;id++){
      const b=structuredClone(binding);b.cycle.batchSeq=id;b.judgment.batch=id;b.judgment.anchor!.id=id;b.judgment.anchor!.batchSeq=id;b.judgment.awardEventIds=[id];b.eventIds=[id]
      i.formal.cycles.push(b);a.cycles.push(b.cycle);a.evidence.push({...event,eventId:id,batchSeq:id,evidenceIds:[100+id]});a.sourceVersions.push({...source,eventId:id,evidenceId:100+id})
      expected.push({originYear:2024,batchSeq:id,state:'not_established',reasons:['not_queried'],refs:{eventIds:[id],evidenceIds:[100+id],queryIds:[],relationIds:[],events:[{id,revision:1}],sources:[{evidenceId:100+id,sha256:aHash}],versions:[],decisions:[],sourceGenerations:[]}})
    }
    expect(comparePlatformComparison(seal(i)).comparison).toEqual({state:'not_established',cycles:expected})
    i.formal.cycles.push(structuredClone(i.formal.cycles[0]!));a.cycles.push(structuredClone(a.cycles[0]!))
    expect(()=>comparePlatformComparison(seal(i))).toThrow(new Error('invalid_cycle_join'))
  })
  it('issue433_null_anchor_requires_direct_members', () => {
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_failed_only_null_anchor')!.input)
    i.formal.cycles[0]!.eventIds=[]
    expect(()=>comparePlatformComparison(i)).toThrow(new Error('invalid_cycle_event'))
  })
  for(const kind of ['nurture','without_evidence'] as const)it('issue433_nonformal_direct_'+kind,()=>{
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_latest_award_only')!.input),e=i.formal.assessment.evidence[0]!
    i.formal.assessment.evidence.push({...e,eventId:99,eventType:kind==='nurture'?'nurture':'award',evidenceIds:kind==='nurture'?[199]:[]})
    i.formal.cycles[0]!.eventIds.push(99)
    expect(()=>comparePlatformComparison(seal(i))).toThrow(new Error('invalid_cycle_event'))
  })
  it('issue433_legacy_error_precedes_binding_error',()=>{
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_coarse_unknown_bucket')!.input)
    i.legacy.snapshotId='invalid'
    expect(()=>comparePlatformComparison(i)).toThrow(new Error('invalid_legacy_snapshot'))
  })
  it('issue433_anchor_error_precedes_incomplete_set',()=>{
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_missing_old_direct_event')!.input)
    i.formal.cycles[0]!.judgment.anchor!.decidedYear=2023
    expect(()=>comparePlatformComparison(i)).toThrow(new Error('invalid_cycle_anchor'))
  })
  it('issue433_dependency_source_cannot_borrow_other_event',()=>{
    const i=structuredClone(issue433Cases.find(c=>c.name==='issue433_resolved_ambiguous_dependency')!.input)
    i.formal.assessment.sourceVersions[1]!.eventId=999
    const result=comparePlatformComparison(seal(i))
    expect(result.comparison).toEqual({state:'not_established',cycles:[{originYear:2024,batchSeq:1,state:'not_established',reasons:['source_requires_revalidation'],refs:{eventIds:[21,23],evidenceIds:[121,123],queryIds:[],relationIds:[],events:[{id:21,revision:1},{id:23,revision:1}],sources:[{evidenceId:121,sha256:aHash}],versions:[],decisions:[],sourceGenerations:[]}}]})
  })
})

// PR434 F1: invalid provided sources must remain blockers after refs filtering.
describe("provided source ownership", () => {
  for (const eventId of [21, 24, 999]) for (const sourceHash of [null, aHash]) {
    it(`issue433_source_owner_${eventId}_${sourceHash === null ? 'null' : 'valid'}`, () => {
      const i = structuredClone(issue433Cases.find(c => c.name === 'issue433_latest_award_only')!.input)
      i.queries = structuredClone(z().queries)
      const source = i.formal.assessment.sourceVersions.find(s => s.evidenceId === 124)!
      Object.assign(source, { eventId, sha256: sourceHash, capturedSha256: sourceHash })
      seal(i)
      const before = JSON.stringify(i)
      expect(i.formal.assessment.evidence.map(e => [e.eventId, e.evidenceIds])).toEqual([[21, [121]], [24, [124]]])
      expect(source.eventId).toBe(eventId)
      expect(source.sha256).toBe(sourceHash)
      const result = comparePlatformComparison(freeze(i))
      const valid = eventId === 24 && sourceHash !== null
      expect(result.observation.state).toBe('no_record')
      expect(result.comparison.state).toBe(valid ? 'unsynchronized' : 'not_established')
      expect(result.comparison.cycles[0]!.reasons).toEqual([valid ? 'no_record_in_applicable_scope' : 'source_requires_revalidation'])
      expect(result.comparison.cycles[0]!.refs.sources).toEqual(eventId === 24
        ? [{ evidenceId: 121, sha256: aHash }, { evidenceId: 124, sha256: sourceHash }]
        : [{ evidenceId: 121, sha256: aHash }])
      expect(JSON.stringify(i)).toBe(before)
    })
  }
})


