// Independent document-framing encoder; no production serializer or result oracle.
function issue435Encode(value: any): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value)
  if (Array.isArray(value)) return '[' + value.map(issue435Encode).join(',') + ']'
  return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + issue435Encode(value[key])).join(',') + '}'
}
function issue435Normalize(value: any, key = ''): any {
  const sets = new Set('titles cycles evidence sourceVersions groups observationRefs existingCorrespondenceIds existingCorrespondences currentDecisionRefs decisionRefs eventIds awardEventIds evidenceIds decisionIds relationIds queryIds observations titleScopeRefs coverage scopeGaps sources publishedNames fieldGaps'.split(' '))
  if (value === null || typeof value !== 'object') return value
  if (Array.isArray(value)) {
    const rows = value.map(item => issue435Normalize(item))
    return sets.has(key) ? rows.sort((a,b) => issue435Encode(a) < issue435Encode(b) ? -1 : issue435Encode(a) > issue435Encode(b) ? 1 : 0) : rows
  }
  const out: Record<string, any> = {}
  for (const k of Object.keys(value)) out[k] = issue435Normalize(value[k], k)
  if ('fetchedCount' in value && 'page' in value && !('maxPage' in value)) out.maxPage = null
  if ('publishedNames' in value && 'gaps' in value && !('fieldGaps' in value)) out.fieldGaps = null
  if ('groups' in value && 'coverage' in value && 'event' in value && !('scopeGaps' in value)) out.scopeGaps = null
  return out
}
describe("frozen contract", () => {
  for (const fixture of issue435Cases) it(fixture.name, () => {
    const i = structuredClone(fixture.input), before = JSON.stringify(i), l = i.legacy
    const legacyHash = hash(JSON.stringify([{enterpriseId:l.enterpriseId,asOf:l.asOf,ruleVersion:l.ruleVersion,assessmentVersion:l.assessmentVersion},l.titles]))
    expect(legacyHash).toBe(l.snapshotId)
    const generations = i.processes.map(p => ({actual:p.sourceGeneration,computed:hash(JSON.stringify(p.sourceRefs))}))
    for (const g of generations) {
      if (fixture.name === 'issue435_old_generation') expect(g.actual).not.toBe(g.computed)
      else expect(g.actual).toBe(g.computed)
    }
    const original = {
      events:i.formal.assessment.evidence.map(e => [e.eventId,e.revision]),
      captures:i.formal.assessment.sourceVersions.map(s => [s.evidenceId,s.capturedRevision]),
      metadata:i.processes.flatMap(p => p.input.groups.flatMap(g => g.observationRefs.map(o => ({protocol:o.businessRecord.hashAlgorithm,hash:o.businessRecord.contentHash}))))
    }
    if (fixture.name === 'issue435_P_event7_rows1_3') {
      expect(original.events).toEqual([[1,7]]);expect(original.captures).toEqual([[101,1],[102,3]])
      expect(original.metadata).toEqual([{protocol:'sha256',hash:'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'}])
    }
    if (fixture.name === 'issue435_P_platform_protocol') {
      expect(original.events).toEqual([[1,1]]);expect(original.captures).toEqual([[101,1]])
      expect(original.metadata).toEqual([{protocol:'platform-row-json-v1',hash:'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'}])
    }
    if (fixture.name === 'issue435_public_safe_facts_synthetic_legacy_shell') {
      expect(original.events).toEqual([[1,2]]);expect(original.captures).toEqual([[1,1]])
      expect(original.metadata).toEqual([{protocol:'platform-row-json-v1',hash:'4e6490a8a34922ffce84362eaa6092c2f0184ac7d287b466a390cda641ef6774'}])
      expect(i.processes[0]!.sourceGeneration).toBe('fd43af8afe6a91ba876af4ba8bb7d7604ccf50768e2d87d9b45407a6d9e6c7e5')
    }
    const scope={enterpriseId:l.enterpriseId,titleCode:i.titleCode,asOf:l.asOf,ruleVersion:l.ruleVersion,assessmentVersion:l.assessmentVersion,legacySnapshotId:l.snapshotId}
    const inputDigest=hash(issue435Encode([i.version,scope,issue435Normalize(i)]))
    expect(inputDigest).toBe(fixture.expected.inputDigest)
    expect(hash(issue435Encode([inputDigest,fixture.expected.observation,fixture.expected.comparison]))).toBe(fixture.expected.resultDigest)
    console.info('ISSUE435_GUARDS ' + JSON.stringify({name:fixture.name,original,legacyHash,generations,inputDigest,expectedResultDigest:fixture.expected.resultDigest}))
    freeze(i)
    try {
      const result=comparePlatformComparison(i)
      console.info('ISSUE435_RESULT ' + JSON.stringify({name:fixture.name,result}))
      expect(result.inputDigest).toBe(inputDigest)
      expect(result.resultDigest).toBe(hash(issue435Encode([inputDigest,result.observation,result.comparison])))
      expect(result).toEqual(fixture.expected)
    } finally {
      expect(JSON.stringify(i)).toBe(before)
      console.info('ISSUE435_IMMUTABLE ' + JSON.stringify({name:fixture.name,unchanged:true}))
    }
  })
})
